// Üretilen dosya: tool/ozgun/uret.py. Kimya · Tepkime hızı, denge ve enerji (zor).
const ozChemistry13Zor = <(String, String, List<String>, String)>[
  ('Bir tepkime için üç deneyde başlangıç hızları ölçülüyor: (1) [A] = 0,10 M, [B] = 0,10 M, r = 2,0×10⁻³ M/s; (2) [A] = 0,20 M, [B] = 0,10 M, r = 4,0×10⁻³ M/s; (3) [A] = 0,20 M, [B] = 0,30 M, r = 3,6×10⁻² M/s. Hız sabiti k kaçtır?', '2,0 M⁻² s⁻¹', ['0,20 M⁻² s⁻¹', '20 M⁻² s⁻¹', '2,0 M⁻¹ s⁻¹'], '1→2\'de [A] iki katına çıkınca hız iki katı: A\'ya göre 1. mertebe. 2→3\'te [B] üç katı, hız 9 katı: B\'ye göre 2. mertebe. k = 2,0×10⁻³ / (0,10·0,10²) = 2,0 M⁻² s⁻¹.'),
  ('X ve Y\'nin tepkimesinde şu başlangıç hızları bulunuyor: [X] = 0,2 M, [Y] = 0,1 M iken r = 1,2×10⁻³ M/s; [X] = 0,4 M, [Y] = 0,1 M iken r = 4,8×10⁻³ M/s; [X] = 0,4 M, [Y] = 0,2 M iken r = 4,8×10⁻³ M/s. Hız sabiti k kaçtır?', '0,03 M⁻¹ s⁻¹', ['0,06 M⁻¹ s⁻¹', '0,30 M⁻¹ s⁻¹', '0,015 M⁻¹ s⁻¹'], '[X] iki katına çıkınca hız 4 katı: X\'e göre 2. mertebe; [Y] değişince hız değişmiyor: Y\'ye göre 0. mertebe. r = k[X]², k = 1,2×10⁻³/0,04 = 0,03 M⁻¹ s⁻¹.'),
  ('İkinci mertebeden (r = k[A]²) bir tepkimede k = 0,50 M⁻¹ s⁻¹ ve [A]₀ = 0,20 M ise yarı ömür kaç saniyedir? (t½ = 1/(k[A]₀))', '10', ['2', '0,10', '1,4'], 't½ = 1/(0,50 × 0,20) = 10 s. İkinci mertebede yarı ömür başlangıç derişimiyle ters orantılıdır.'),
  ('Aktifleşme enerjisi 50 kJ/mol olan bir tepkimenin sıcaklığı 300 K\'den 310 K\'e çıkarılırsa hız sabiti yaklaşık kaç katına çıkar? (R = 8,314 J/(mol·K), e^0,647 ≈ 1,91)', '1,9', ['1,10', '3,2', '6,5'], 'ln(k₂/k₁) = (Ea/R)(1/T₁ − 1/T₂) = (50 000/8,314)(1/300 − 1/310) ≈ 0,647; k₂/k₁ = e^0,647 ≈ 1,9.'),
  ('Bir gazın Maxwell–Boltzmann enerji dağılımı eğrisi sıcaklık artınca yassılaşıp sağa kayar. Eğrinin altında kalan toplam alan ise değişmez. Bunun nedeni nedir?', 'Toplam tanecik sayısı sabit kalır, yalnız enerji dağılımı değişir', ['Taneciklerin bir kısmı yok olur', 'Eşik enerjisi sıcaklıkla birlikte artar', 'Taneciklerin kütlesi sıcaklıkla artar'], 'Alan toplam tanecik sayısını gösterir ve sıcaklıkla değişmez. Sıcaklık yükselince eşik enerjisini aşan tanecik oranı artar, hız bu yüzden yükselir.'),
  ('Enerji profili çizilen bir tepkimede ara ürün ile aktifleşmiş kompleks arasındaki temel fark nedir?', 'Ara ürün enerji profilinde çukur, aktifleşmiş kompleks tepe noktasıdır', ['Ara ürün tepkimede hiç oluşmaz, aktifleşmiş kompleks sürekli oluşur', 'Ara ürün en yüksek enerjili, aktifleşmiş kompleks en düşük enerjilidir', 'Ara ürün katalizördür, aktifleşmiş kompleks ürüne denktir'], 'Ara ürün iki tepe arasındaki yerel enerji minimumundadır ve bazen ayrıştırılabilir. Aktifleşmiş kompleks ise enerji tepesinde, ömrü çok kısa geçiş hâlidir.'),
  ('2NO + O₂ → 2NO₂ tepkimesi için önerilen mekanizma: (1) NO + O₂ ⇌ NO₃ (hızlı denge), (2) NO₃ + NO → 2NO₂ (yavaş). Bu mekanizmadan türetilen hız ifadesi hangisidir?', 'r = k[NO]²[O₂]', ['r = k[NO₃][NO]', 'r = k[NO][O₂]', 'r = k[NO]²'], 'Yavaş basamakta r = k₂[NO₃][NO]. Hızlı dengeden [NO₃] = K[NO][O₂] bulunur; yerine konunca r = k[NO]²[O₂] olur. Ara ürün hız ifadesinde yer almaz.'),
  ('2O₃ → 3O₂ tepkimesi için önerilen mekanizma: (1) O₃ ⇌ O₂ + O (hızlı denge), (2) O + O₃ → 2O₂ (yavaş). Bu mekanizmaya göre hız ifadesi hangisidir?', 'r = k[O₃]²/[O₂]', ['r = k[O₃]²', 'r = k[O₃][O₂]', 'r = k[O₃]'], 'Yavaş basamakta r = k₂[O][O₃]. Hızlı dengeden [O] = K[O₃]/[O₂]; yerine konunca r = k[O₃]²/[O₂] bulunur. Ürün O₂\'nin derişimi hızı düşürür.'),
  ('Bir tepkimede katalizör kullanılınca ileri yönün aktifleşme enerjisi 90 kJ\'den 60 kJ\'e düşüyor. Katalizörsüz geri tepkimenin aktifleşme enerjisi 130 kJ olduğuna göre katalizörlü geri tepkimenin aktifleşme enerjisi kaç kJ\'dir?', '100', ['60', '130,0', '160'], 'Katalizör ileri ve geri yönün enerji bariyerini aynı miktarda (30 kJ) düşürür; ΔH = 90 − 130 = −40 kJ değişmez. Geri Ea = 130 − 30 = 100 kJ olur.'),
  ('Bir tepkimenin yavaş basamağından önce hızlı bir denge basamağı bulunuyorsa hız ifadesine ara ürünün derişimi doğrudan yazılamaz. Bu durumda ara ürünün derişimi nasıl ifade edilir?', 'Hızlı dengenin K\'sı ile giren türlerin derişimleri cinsinden', ['Ara ürünün derişimi sıfır kabul edilerek hesaba katılmaz', 'Ara ürün derişimi başlangıçtaki katalizör derişimine eşitlenir', 'Yavaş basamağın aktifleşme enerjisinden hesaplanır'], 'Hızlı basamak dengede kabul edilir; K = [ara ürün]/[girenler] ilişkisiyle ara ürün derişimi giren maddelerin derişimlerine çevrilir.'),
  ('Asitlendirilmiş KMnO₄ çözeltisi ile oksalik asit tepkimesinde başlangıçta renk çok yavaş açılır, sonra giderek hızlanır. Bu gözlem hangi olayla açıklanır?', 'Ürün Mn²⁺\'nin tepkimeyi katalizlemesi', ['Çözeltinin tepkime sırasında soğuması ve yavaşlaması', 'Girenlerin derişiminin zamanla gittikçe artması', 'Katalizörün tepkime başında tükenmesi'], 'Tepkime ilerledikçe oluşan Mn²⁺ iyonları katalizör gibi davranır; hız düşmek yerine bir süre artar. Böyle ürünün kendi tepkimesini hızlandırmasına otokataliz denir.'),
  ('Yarışmalı (kompetitif) bir enzim inhibitörü için hangisi doğrudur?', 'Substrata benzer, aktif merkeze bağlanır; substrat artınca etkisi aşılır', ['Aktif merkez dışına bağlanır; substrat artırılınca etkisi daha da artar', 'Enzimi tamamen sindirerek parçalar ve yok eder', 'Vmax değerini kalıcı olarak yarıya indirir ve değişmez'], 'Yarışmalı inhibitör substratla aktif merkez için yarışır. Substrat çok artırılırsa inhibitörün yerini alır ve Vmax\'a yeniden ulaşılabilir.'),
  ('Yarışmasız (kompetitif olmayan) inhibitör aktif merkez dışında bir bölgeye bağlanıp enzimin şeklini bozuyor. Substrat derişimi çok yükseltilse de hız neden eski Vmax değerine ulaşamaz?', 'İnhibitörlü enzimler substrat fazlalığıyla bile etkin hâle gelmez', ['Substrat arttıkça inhibitör enzimden ayrılıp yeniden çalışır', 'Aktif merkez genişleyip fazla substratı da bağlar', 'İnhibitör fazla substratı kendine dönüştürerek harcar'], 'İnhibitör bağlanan enzim molekülleri işlevsiz kalır; substrat fazlalığı onları geri kazandırmaz. Bu yüzden ulaşılabilir en yüksek hız (Vmax) düşer.'),
  ('Enzimli bir tepkimede substrat derişimi çok düşükken hız substrat derişimiyle doğru orantılıdır; çok yüksekken ise derişimden bağımsızdır. Bu iki bölgede tepkime mertebesi sırasıyla ne olur?', 'Birinci mertebe, sıfırıncı mertebe', ['Sıfırıncı mertebe, sonra birinci mertebe', 'İkinci mertebe, birinci mertebe', 'Birinci mertebe, ikinci mertebe'], 'Düşük derişimde hız ∝ [S] olduğundan birinci, doygunlukta hız sabit kaldığından sıfırıncı mertebe davranışı görülür.'),
  ('2 L\'lik kaba 2 mol SO₂ ve 1 mol O₂ konuyor. 2SO₂ + O₂ ⇌ 2SO₃ dengesi kurulduğunda 1 mol SO₃ oluşmuştur. Bu sıcaklıkta Kc kaçtır?', '4 M⁻¹', ['2 M⁻¹', '8 M⁻¹', '0,25 M⁻¹'], 'Dengede SO₂ 1 mol, O₂ 0,5 mol, SO₃ 1 mol; V = 2 L olduğundan derişimler 0,5; 0,25; 0,5 M\'dir. Kc = 0,25/(0,25·0,25) = 4 M⁻¹.'),
  ('Denge sabiti 16 olan A + B ⇌ C + D sisteminde kaba yalnızca C ve D\'den birer mol (hacim 1 L) konursa A\'nın denge derişimi nedir?', '0,20', ['0,80', '0,400', '0,05'], 'Ters yönde K′ = 1/16 olur. Oluşan A için x²/(1−x)² = 1/16, x/(1−x) = 1/4 ve x = 0,20 M bulunur.'),
  ('Bir tepkimenin ileri hız sabiti k₁ = 2,0×10⁻² s⁻¹, geri hız sabiti k₋₁ = 4,0×10⁻⁴ s⁻¹\'dir. Her iki yön de temel basamak ise denge sabiti (Kc) kaçtır?', '50', ['5', '500', '0,02'], 'Dengede ileri ve geri hızlar eşittir: k₁[A] = k₋₁[B]. Kc = k₁/k₋₁ = 0,020/0,00040 = 50.'),
  ('2SO₂(g) + O₂(g) ⇌ 2SO₃(g) tepkimesinin 500 K\'de Kp değeri 0,010 atm⁻¹\'dir. Aynı sıcaklıkta Kc kaçtır? (R = 0,082 L·atm/(mol·K), RT ≈ 41)', '0,41', ['0,010', '2,4×10⁻⁴', '4,1'], 'Δn = −1 olduğundan Kp = Kc(RT)⁻¹ ve Kc = Kp·RT = 0,010 × 41 = 0,41 M⁻¹.'),
  ('Kapalı bir kapta CaCO₃(k) ⇌ CaO(k) + CO₂(g) dengesi kurulmuş ve CO₂ basıncı 0,25 atm olmuştur. Sıcaklık sabitken kap hacmi iki katına çıkarılıp denge yeniden kurulduğunda, kapta hâlâ katı CaCO₃ ve CaO bulunuyorsa CO₂ basıncı kaç atm olur?', '0,25', ['0,125', '0,50', '0,0625'], 'Kp = P(CO₂) olduğundan sıcaklık değişmedikçe denge basıncı sabittir. Hacim artınca daha fazla CaCO₃ ayrışır ve basınç yine 0,25 atm\'ye döner.'),
  ('1 atm toplam basınçta N₂O₄ ⇌ 2NO₂ dengesinde başlangıçtaki N₂O₄\'ün yarısı (α = 0,5) ayrışmıştır. Kp kaç atm\'dir?', '1,33', ['0,500', '2,00', '4,00'], '1 mol N₂O₄ ile başlanırsa denge karışımı 0,5 mol N₂O₄ ve 1 mol NO₂ içerir (toplam 1,5 mol). P(N₂O₄) = 1/3, P(NO₂) = 2/3 atm; Kp = (4/9)/(1/3) = 4/3 ≈ 1,33.'),
  ('2A(g) ⇌ B(g) dengesindeki sistemin hacmi sıcaklık sabitken yarıya indiriliyor. Hacim değişiminden hemen sonra reaksiyon bölümü Q, denge sabiti K\'nın kaç katıdır?', '1/2', ['2,00', '4', '1'], 'Derişimler iki katına çıkınca Q = (2[B])/(2[A])² = [B]/(2[A]²) = K/2 olur. Q < K olduğundan denge ürün (B) yönüne kayar.'),
  ('N₂O₄(g) ⇌ 2NO₂(g) dengesinde hacim sıcaklık sabitken yarıya indirilirse, hemen sonraki Q değeri K\'nın kaç katıdır ve denge hangi yöne kayar?', '2 katı; N₂O₄ yönüne', ['1/2 katı; ürünler yönüne', '2 katı; NO₂ yönüne', '1 katı; denge kaymaz'], 'Derişimler iki katına çıkınca pay 4 kat, payda 2 kat artar; Q = 2K olur. Q > K olduğundan denge, gaz mol sayısı azalan N₂O₄ yönüne kayar.'),
  ('Kontakt yönteminde SO₂\'nin SO₃\'e yükseltgenmesinde dönüşüm oranı 1–2 atm gibi düşük basınçta bile yüksek olduğundan çok yüksek basınç kullanılmaz. Bunun gerekçesi hangisidir?', 'Ek verim, ekipman ve enerji maliyetini karşılamaz', ['Basınç arttıkça oluşan SO₃ hızla ayrışır', 'Yüksek basınç katalizörü kalıcı olarak zehirler', 'Basınç artışı Kc değerini belirgin şekilde küçültür'], 'Gaz mol sayısı azalan tepkimede basınç verimi artırır, fakat verim zaten yüksektir; yüksek basınçlı ekipman maliyeti ek kazancı haklı çıkarmaz.'),
  ('Pistonlu bir şırıngada N₂O₄ ⇌ 2NO₂ dengesindeki kahverengi gaz hızla sıkıştırıldığında renk için ne gözlenir?', 'Önce koyulaşır, sonra biraz açılır', ['Önce açılır, sonra biraz koyulaşır', 'Renk hiç değişmez', 'Renk sürekli koyulaşır'], 'Sıkıştırınca derişim anlık artar, renk koyulaşır. Sonra denge gaz mol sayısı az olan N₂O₄ yönüne kayar ve renk bir miktar açılır.'),
  ('Bir tepkime için ln K değerleri 1/T\'ye karşı çizilince eğim +6000 K bulunuyor. Tepkimenin ΔH değeri yaklaşık kaç kJ/mol\'dür? (R = 8,314 J/(mol·K))', '−50', ['+50', '−6', '+720'], 'van\'t Hoff bağıntısında eğim = −ΔH/R\'dir. ΔH = −6000 × 8,314 ≈ −50 kJ/mol; sıcaklık artınca K azaldığından tepkime ekzotermiktir.'),
  ('ΔH° = +40 kJ/mol olan bir tepkimenin sıcaklığı 300 K\'den 310 K\'e çıkarılıyor. Denge sabiti yaklaşık kaç katına çıkar? (R = 8,314 J/(mol·K), e^0,517 ≈ 1,68)', '1,7', ['1,1', '3,20', '0,6'], 'ln(K₂/K₁) = (ΔH/R)(1/T₁ − 1/T₂) = (40 000/8,314)(1,075×10⁻⁴) ≈ 0,517; K₂/K₁ ≈ 1,7. Endotermik tepkimede K artar.'),
  ('298 K\'de ΔG° = +23 kJ/mol olan bir tepkimenin denge sabiti yaklaşık kaçtır? (RT = 2,48 kJ/mol)', '10⁻⁴', ['10⁴', '10,0⁻¹', '10⁻⁹'], 'ln K = −23/2,48 ≈ −9,3 olduğundan K ≈ e^(−9,3) ≈ 10⁻⁴. ΔG° pozitif olduğu için K < 1\'dir.'),
  ('Bir endüstriyel süreçte katalizör kullanımı, ekzotermik denge tepkimesinin verimine dolaylı olarak nasıl katkı sağlayabilir?', 'Daha düşük T\'de aynı hıza ulaştırarak verim kazandırır', ['Denge sabitini doğrudan büyüterek verimi artırır', 'Girenlerin ürüne tam dönüşmesini zorlayarak', 'Tepkimenin ΔH değerini küçülterek'], 'Katalizör K\'yı değiştirmez. Ancak istenen hıza daha düşük sıcaklıkta ulaşıldığında ekzotermik dengede K daha büyük olur ve verim artar.'),
  ('100 °C\'ye ısıtılmış 50 g metal parça, 20 °C\'deki 100 g suya atılıyor. Son sıcaklık 25 °C olduğuna göre metalin özgül ısısı yaklaşık kaç J/(g·°C)\'dir? (Suyun özgül ısısı 4,18 J/(g·°C); ısı kaybı ihmal edilsin.)', '0,56', ['1,12', '2,23', '0,280'], 'Metalin verdiği ısı sudaki alınan ısıya eşittir: 50·c·75 = 100·4,18·5 → c = 2090/3750 ≈ 0,56 J/(g·°C).'),
  ('0 °C\'de 50 g buz ile 20 °C\'de 400 g su ısı kaybı olmadan karıştırılıyor. Buzun erime ısısı 334 J/g, suyun özgül ısısı 4,18 J/(g·°C) ise denge sıcaklığı yaklaşık kaç °C olur?', '8,9', ['4,2', '10,0', '13,3'], 'Suyun verdiği ısı = buzun erimesi + eriyen suyun ısınması: 400·4,18·(20 − T) = 50·334 + 50·4,18·T. Çözülünce T ≈ 8,9 °C bulunur.'),
  ('S + O₂ → SO₂ için ΔH = −297 kJ ve 2SO₃ → 2SO₂ + O₂ için ΔH = +198 kJ\'dir. S + 3/2 O₂ → SO₃ tepkimesinin ΔH değeri kaç kJ\'dir?', '−396', ['−99,0', '−495', '−198'], 'İkinci denklem ters çevrilip 1/2 ile çarpılınca SO₂ + ½O₂ → SO₃ için ΔH = −99 kJ olur. Birincisiyle toplanınca −297 − 99 = −396 kJ bulunur.'),
  ('ΔH°f değerleri Fe₂O₃(k) −824, CO(g) −110,5 ve CO₂(g) −393,5 kJ/mol\'dür. Fe₂O₃ + 3CO → 2Fe + 3CO₂ tepkimesinin ΔH değeri kaç kJ\'dir?', '−25', ['+25', '−1180', '−1706'], 'ΔH = [3(−393,5) + 0] − [−824 + 3(−110,5)] = −1180,5 − (−1155,5) = −25 kJ.'),
  ('Bağ enerjileri (kJ/mol): C–H 414, O=O 498, C=O 799, O–H 463. CH₄ + 2O₂ → CO₂ + 2H₂O(g) tepkimesinin ΔH değeri yaklaşık kaç kJ\'dir?', '−798', ['+798', '−3450', '−1596'], 'Kırılan: 4(414) + 2(498) = 2652 kJ. Oluşan: 2(799) + 4(463) = 3450 kJ. ΔH = 2652 − 3450 = −798 kJ.'),
  ('CaCO₃(k) → CaO(k) + CO₂(g) için ΔH = +178 kJ ve ΔS = +161 J/K\'dir. Tepkimenin istemli hâle geçtiği sıcaklık yaklaşık kaç K\'dir? (ΔH ve ΔS sıcaklıkla değişmiyor kabul edilsin.)', '1105', ['298,0', '178', '2870'], 'ΔG = 0 koşulunda T = ΔH/ΔS = 178 000 J / 161 J/K ≈ 1105 K\'dir. Bu sıcaklığın üstünde ΔG negatif olur.'),
  ('Amonyak sentezinin ΔH = −92 kJ ve ΔS = −199 J/K değerleri sıcaklıktan bağımsız kabul edilirse tepkimenin istemli olduğu en yüksek sıcaklık yaklaşık kaç K\'dir?', '462', ['298', '92', '1010'], 'ΔG = 0 için T = ΔH/ΔS = (−92 000)/(−199) ≈ 462 K\'dir. Bunun üstünde ΔG pozitif olur; bu yüzden endüstride hız için katalizör ve basınç kullanılır.'),
  ('Elmas ve grafitin standart mutlak entropileri karşılaştırıldığında hangisi doğrudur?', 'Grafitin entropisi daha büyüktür', ['Elmasın entropisi grafitinkinden büyüktür', 'İkisinin entropisi eşittir', 'İkisi de sıfırdır'], 'Elmasta atomlar sert, üç boyutlu bir ağda çok sıkı bağlıdır; titreşim serbestliği azdır. Grafitte katmanlar arası zayıf bağlar daha fazla hareket serbestliği sağlar.'),
  ('N₂ + 3H₂ → 2NH₃ tepkimesinde 298 K\'de ΔH = −92 kJ\'dir. ΔH = ΔU + ΔnRT bağıntısıyla ΔU yaklaşık kaç kJ\'dir? (RT = 2,48 kJ/mol)', '−87,0', ['−97,0', '−92,0', '−84,50'], 'Δn = 2 − 4 = −2\'dir. ΔU = ΔH − ΔnRT = −92 − (−2)(2,48) = −92 + 4,96 ≈ −87,0 kJ.'),
  ('İdeal bir gaz sabit sıcaklıkta (izotermal) genleşirken iç enerjisi değişmez. Bu durumda q ve w arasında nasıl bir ilişki vardır?', 'q = −w; gaz ısı alır, iş yapar', ['q = w; gaz ısı verir ve iş yapar', 'q = 0 ve w = 0', 'w = 0 ve q > 0'], 'İdeal gazın iç enerjisi yalnızca sıcaklığa bağlıdır; ΔU = 0 olduğundan q = −w\'dir. Gaz iş yaparken kaybettiği enerjiyi çevreden aldığı ısıyla karşılar.'),
  ('1 mol monoatomik ideal gaz sabit hacimde 100 K ısıtılıyor. Verilen ısı yaklaşık kaç kJ\'dir? (Cv = 3/2·R, R = 8,314 J/(mol·K))', '1,25', ['2,08', '0,83', '12,50'], 'Sabit hacimde q = nCvΔT = 1 × 1,5 × 8,314 × 100 ≈ 1247 J ≈ 1,25 kJ.'),
  ('100 °C\'de 1 mol suyun buharlaşma entalpisi ΔH = +40,7 kJ\'dir. Aynı olay için ΔU yaklaşık kaç kJ\'dir? (RT = 3,10 kJ/mol; buhar ideal kabul edilsin)', '37,6', ['43,80', '40,7', '3,10'], 'Δn = +1 mol gazdır. ΔU = ΔH − ΔnRT = 40,7 − 3,10 = 37,6 kJ. Buharlaşan sistemin bir kısmı genleşme işine harcanır.'),
  ('Bir öğrenci \'Bir tepkimenin ısısı izlenen yola bağlıdır, çünkü ısı bir durum fonksiyonudur\' diyor. Bu ifadeyi değerlendiren öğretmen ne söylemelidir?', 'Isı durum fonksiyonu değildir, ΔH ise yoldan bağımsızdır', ['İfade doğrudur, çünkü ısı ve entalpi yola bağlıdır', 'ΔH yola bağlıdır, ısıya bağlı değildir', 'Hem ısı hem entalpi tamamen yoldan bağımsızdır'], 'İfade kendi içinde çelişkilidir: durum fonksiyonları yoldan bağımsızdır. Isı genelde yola bağlıdır ama sabit basınçtaki ısı ΔH\'a eşit olduğundan Hess yasası geçerlidir.'),
  ('1 mol H₂ ile 0,5 mol O₂ karışımı tamamen tepkimeye girerek H₂O(s) oluşturuyor (H₂ + ½O₂ → H₂O(s), ΔH = −286 kJ). Açığa çıkan ısı kaç kJ\'dir?', '286', ['572', '143', '1144'], '1 mol H₂ ile 0,5 mol O₂ stokiyometrik oranda tepkimeye girer ve 1 mol H₂O(s) oluşur; denklem 1 mol H₂O için ΔH = −286 kJ verdiğinden 286 kJ ısı açığa çıkar.'),
  ('1,0 kg suyu 10 °C ısıtmak için (c = 4,18 J/(g·°C)) metan yakılıyor. Isı kaybı yoksa gerekli CH₄ kütlesi yaklaşık kaç gramdır? (ΔH_yanma = −890 kJ/mol, CH₄ = 16 g/mol)', '0,75', ['7,5', '0,047', '12'], 'Gerekli ısı q = 1000 × 4,18 × 10 = 41,8 kJ\'dir. Mol = 41,8/890 ≈ 0,047; kütle = 0,047 × 16 ≈ 0,75 g.'),
  ('10 g 100 °C\'deki su buharı, 20 °C\'deki suya dönüşene kadar soğutuluyor. Açığa çıkan toplam ısı yaklaşık kaç kJ\'dir? (Buharlaşma ısısı 2260 J/g, suyun özgül ısısı 4,18 J/(g·°C))', '25,9', ['22,6', '3,3', '42,60'], 'Yoğuşma: 10 × 2260 = 22 600 J. Suyun 100 → 20 °C soğuması: 10 × 4,18 × 80 = 3344 J. Toplam ≈ 25 944 J ≈ 25,9 kJ.'),
  ('Trouton kuralına göre birçok sıvıda buharlaşma entropisi yaklaşık 88 J/(mol·K)\'dir. Normal kaynama noktası 350 K olan böyle bir sıvının buharlaşma entalpisi yaklaşık kaç kJ/mol\'dür?', '30,8', ['88,0', '0,250', '3,08'], 'Kaynama noktasında ΔG = 0 olduğundan ΔH = TΔS = 350 × 88 = 30 800 J/mol ≈ 30,8 kJ/mol.'),
  ('Su ve etanolün buharlaşma entropileri Trouton değeri (≈ 88 J/(mol·K)) ile karşılaştırıldığında daha büyük çıkar. Bu sapma nasıl yorumlanır?', 'Sıvıdaki H-bağlı düzen, buharlaşmada büyük düzensizlik artışı yaratır', ['Gaz hâlin sıvıdan daha düzenli bir yapıda olması', 'Sıvı hâldeki suyun mutlak entropisinin sıfır olması', 'Buharlaşma ısısının her zaman negatif olması gerekliliği'], 'Hidrojen bağlı sıvılar daha düzenli yapıdadır; gaz hâle geçince entropi artışı normalden büyük olur. Bu da Trouton kuralından sapma yaratır.'),
  ('Hız yasası r = k[A]^(3/2) olan bir tepkimede derişim M, zaman s cinsinden alınırsa k\'nın birimi ne olur?', 'M^(−1/2) s⁻¹', ['M⁻¹ s⁻¹', 'M^(1/2) s⁻¹', 's⁻¹'], 'k = r/[A]^(3/2) olduğundan birim (M s⁻¹)/(M^(3/2)) = M^(−1/2) s⁻¹ olur.'),
  ('H₂ + Br₂ → 2HBr tepkimesinin mekanizmasında önce Br₂ ⇌ 2Br (hızlı denge), sonra Br + H₂ → HBr + H (yavaş) basamağı yer alsın. Bu iki basamağa göre toplam hız ifadesi hangisidir?', 'r = k[H₂][Br₂]^(1/2)', ['r = k[H₂][Br₂]', 'r = k[Br][Br₂]', 'r = k[H₂]²'], 'Yavaş basamakta r = k₂[Br][H₂]. Hızlı dengeden [Br] = K^(1/2)[Br₂]^(1/2) olduğundan r = k[H₂][Br₂]^(1/2) bulunur; kesirli mertebe mekanizmadan çıkar.'),
  ('Bir tepkimenin hız yasası r = k[A][B]^(1/2) bulunmuştur. Bu sonuç hakkında hangisi söylenebilir?', 'Tepkime temel (tek basamaklı) değildir', ['Tepkime tek basamakta gerçekleşir', 'Moleküleriyet 1,5\'tir', 'Katalizör içermelidir'], 'Temel basamaklarda mertebeler tam sayıdır (katsayılara eşit). Kesirli mertebe, tepkimenin birden çok basamaklı mekanizmayla yürüdüğünü gösterir.'),
  ('N₂(g) + 3H₂(g) ⇌ 2NH₃(g) dengesinde basınç artırıldığında ileri ve geri hızlar için hangisi doğrudur?', 'İkisi de artar, ileri hız daha çok artar', ['İkisi de artar, geri hız daha çok artar', 'İleri artar, geri azalır', 'İkisi de aynı oranda artar'], 'Derişimler arttığı için iki hız da artar. İleri hız [H₂]³[N₂] ile (4. mertebe) arttığından geri hızdan (2. mertebe) daha fazla artar ve denge ürüne kayar.'),
  ('Ekzotermik bir dengede sıcaklık artırıldığında ileri ve geri tepkime hızlarında ne gözlenir?', 'İkisi de artar, geri hız daha çok artar', ['İkisi de azalır', 'İleri hız artar, geri hız azalır', 'İkisi de aynı oranda artar'], 'Sıcaklık artınca her iki hız sabiti artar; aktifleşme enerjisi daha büyük olan geri yön daha çok hızlanır. Denge girenler yönüne kayar.'),
  ('Standart yanma entalpileri C(grafit) −394, H₂(g) −286 ve C₂H₂(g) −1300 kJ/mol\'dür. 2C(grafit) + H₂(g) → C₂H₂(g) tepkimesinin ΔH değeri (asetilenin oluşum entalpisi) kaç kJ\'dir?', '+226', ['−226', '+1980', '−1980'], 'Oluşum entalpisi = Σ(girenlerin yanma entalpileri) − Σ(ürünlerin yanma entalpileri) = [2(−394) + (−286)] − (−1300) = −1074 + 1300 = +226 kJ.'),
  ('Yanma entalpileri C(grafit) −394, H₂(g) −286 ve C₂H₅OH(s) −1367 kJ/mol\'dür. 2C + 3H₂ + ½O₂ → C₂H₅OH(s) tepkimesinin ΔH değeri yaklaşık kaç kJ\'dir?', '−279', ['+279', '−2447', '+2447'], 'ΔH_oluşum = [2(−394) + 3(−286)] − (−1367) = (−788 − 858) + 1367 = −279 kJ.'),
  ('Hidrojen peroksidin elementlerinden oluşumunda ΔH = −188 kJ, sıvı suyun elementlerinden oluşumunda ΔH = −286 kJ\'dir (H₂ + O₂ → H₂O₂ ve H₂ + ½O₂ → H₂O). 2H₂O₂(s) → 2H₂O(s) + O₂(g) ayrışmasında entalpi değişimi kaç kJ\'dir?', '−196', ['+196', '−98,0', '−662'], 'Birinci denklemi ters çevirip 2 ile çarpınca +376 kJ, ikinciyi 2 ile çarpınca −572 kJ bulunur. Toplam ΔH = 376 − 572 = −196 kJ.'),
  ('ΔH°f değerleri NH₃(g) −46, NO(g) +90 ve H₂O(g) −242 kJ/mol\'dür. 4NH₃ + 5O₂ → 4NO + 6H₂O(g) tepkimesinin ΔH değeri kaç kJ\'dir?', '−908', ['+908', '−1636', '−454'], 'ΔH = [4(90) + 6(−242)] − [4(−46) + 0] = (360 − 1452) + 184 = −908 kJ. Ostwald yönteminin ilk basamağı güçlü ekzotermiktir.'),
  ('NH₄NO₃\'ın suda çözünme entalpisi yaklaşık +25,7 kJ/mol\'dür. 8,0 g NH₄NO₃ (80 g/mol) 100 g suda çözülürse sıcaklık yaklaşık kaç °C düşer? (c = 4,18 J/(g·°C); çözelti kütlesi ve kalorimetre ısınması ihmal edilsin.)', '6,1', ['61', '0,61', '2,6'], '8,0 g = 0,10 mol; alınan ısı 2,57 kJ = 2570 J. ΔT = 2570/(100 × 4,18) ≈ 6,1 °C soğuma olur.'),
  ('Termodinamik denge sabiti K\'nın genellikle birimsiz verilmesinin nedeni nedir?', 'Standart duruma oranlanmış aktivitelerle yazılır', ['K her koşulda tam olarak 1\'e eşit olduğu için birimi yoktur', 'Birimler hesaplamada önemsizdir', 'Gazlar için derişim tanımlı değildir'], 'Aktiviteler standart duruma göre bağıl niceliklerdir ve birimsizdir; bu yüzden termodinamik K birimsizdir. Kc ya da Kp ise birimli yazılabilir.'),
  ('Sıcaklığı 500 K olan bir kaynaktan 1000 J ısı, 300 K\'deki bir kaba kendiliğinden geçiyor. Toplam entropi değişimi (ΔS = q/T hesabıyla) yaklaşık kaç J/K\'dir?', '+1,33', ['−1,330', '0,00', '+3,33'], 'Kaynağın entropisi −1000/500 = −2 J/K, kabın entropisi +1000/300 ≈ +3,33 J/K değişir. Toplam ≈ +1,33 J/K, yani pozitiftir; ısı sıcaktan soğuğa kendiliğinden akar.'),
  ('50 mL 2,0 M HCl ile 50 mL 2,0 M NaOH karıştırılıyor. Nötrleşme entalpisi −56 kJ/mol, çözelti özgül ısısı 4,18 J/(g·°C) ve yoğunluk 1,0 g/mL ise sıcaklık artışı yaklaşık kaç °C olur?', '13,4', ['6,70', '26,80', '3,3'], '0,10 mol su oluşur; açığa çıkan ısı 5600 J\'dür. Isınan kütle 100 g\'dır. ΔT = 5600/(100 × 4,18) ≈ 13,4 °C.'),
  ('Isı yalıtımı iyi olmayan bir kalorimetrede ekzotermik bir tepkime sonrası sıcaklık en yüksek değere ulaşıp sonra yavaşça düşüyor. Doğru ΔT\'yi bulmak için ne yapılır?', 'Sıcaklık–zaman verilerine geriye doğru ekstrapolasyon yapılır', ['Sıcaklığın en düşük değeri alınır', 'Kalorimetre değiştirilir', 'Tepkime tekrar edilmez, ilk ölçüm kullanılır'], 'Isı kaybı nedeniyle en yüksek değer gerçeğin altındadır. Soğuma doğrusu karıştırma anına geri uzatılarak ısı kaybı düzeltilmiş ΔT bulunur.'),
  ('Bir tepkimenin K değeri sıcaklık artınca küçülüyorsa ΔH° ve K\'nın ln K–1/T grafiğindeki eğimi için hangisi doğrudur?', 'ΔH° < 0 ve eğim pozitiftir', ['ΔH° > 0 ve eğim pozitiftir', 'ΔH° < 0 ve eğim negatiftir', 'ΔH° > 0 ve eğim negatiftir'], 'K sıcaklıkla azalıyorsa tepkime ekzotermiktir. Eğim = −ΔH°/R olduğundan ΔH° < 0 için eğim pozitiftir.'),
  ('2N₂O₅(g) → 4NO₂(g) + O₂(g) tepkimesi sabit hacimli kapta 1,0 atm N₂O₅ ile başlıyor ve N₂O₅\'in yarısı ayrıştığında kaptaki toplam basınç kaç atm olur? (Sıcaklık sabit)', '1,75', ['1,500', '2,50', '1,25'], 'N₂O₅\'in yarısı (0,5 atm) ayrışınca 0,5 atm N₂O₅ kalır. Ayrışan 0,5 atm N₂O₅ için 2 mol → 5 mol gaz olduğundan 0,5 × 5/2 = 1,25 atm gaz oluşur. Toplam = 0,5 + 1,25 = 1,75 atm.'),
  ('2NO + O₂ → 2NO₂ tepkimesinin hızı, sıcaklık artınca bazı sıcaklık aralıklarında azalabilir. Bunun mekanizmadaki açıklaması nedir?', 'Ekzotermik hızlı ön dengenin sıcaklıkla ara ürün derişimini azaltması', ['Aktifleşme enerjisinin sıcaklıkla sürekli artması', 'Gazların sıcakta çarpışmaması', 'Katalizörün sıcakta çözünmesi'], 'Mekanizmada ekzotermik hızlı bir ön denge (2NO ⇌ N₂O₂) vardır; sıcaklık artınca ara ürün derişimi düşer. Bu etki k₂\'nin artışını aşarsa toplam hız düşebilir.'),
  ('H₂(g) + ½O₂(g) → H₂O(s) tepkimesi için 298 K\'de ΔH = −286 kJ\'dir. ΔU değeri yaklaşık kaç kJ\'dir? (RT = 2,48 kJ/mol)', '−282,3', ['−289,7', '−286,00', '−283,5'], 'Gaz mol sayısı değişimi Δn = 0 − 1,5 = −1,5\'tir. ΔU = ΔH − ΔnRT = −286 + 1,5 × 2,48 = −282,3 kJ.'),
  ('Yalnız 1,0 M HI ile başlanan 2HI(g) ⇌ H₂(g) + I₂(g) dengesinde Kc = 1/64\'tür. Dengede [HI] kaç M olur?', '0,80', ['0,20', '0,50', '0,900'], 'H₂ ve I₂ için y alınırsa y²/(1−2y)² = 1/64 ve y/(1−2y) = 1/8 olur; y = 0,10 M. [HI] = 1,0 − 0,20 = 0,80 M.'),
  ('N₂(g) + O₂(g) ⇌ 2NO(g) tepkimesinin çok yüksek bir sıcaklıkta Kc = 4,0×10⁻⁴\'tür. Başlangıçta [N₂] = [O₂] = 0,10 M ise dengede yaklaşık [NO] kaç M olur?', '2,0×10⁻³', ['4,00×10⁻⁴', '1,0×10⁻³', '2,0×10⁻²'], 'Kc = (2x)²/(0,10 − x)² = 4,0×10⁻⁴ → 2x/(0,10 − x) = 0,020. x ≈ 1,0×10⁻³ M bulunur; [NO] = 2x ≈ 2,0×10⁻³ M.'),
  ('Bir tepkimede başlangıç hızları: (1) [A] = 0,10 M, [B] = 0,10 M, r = 1,0×10⁻⁴ M/s; (2) [A] = 0,30 M, [B] = 0,10 M, r = 9,0×10⁻⁴ M/s; (3) [A] = 0,30 M, [B] = 0,20 M, r = 1,8×10⁻³ M/s. [A] = 0,50 M ve [B] = 0,40 M iken hız kaç M/s olur?', '1,0×10⁻²', ['5,0×10⁻³', '2,00×10⁻³', '2,5×10⁻³'], 'A\'ya göre 2. mertebe, B\'ye göre 1. mertebedir; r = k[A]²[B], k = 1,0×10⁻⁴/(0,01 × 0,10) = 0,10 M⁻² s⁻¹. r = 0,10 × 0,25 × 0,40 = 1,0×10⁻² M/s.'),
  ('Platin yüzeyinde NH₃\'ün ayrışmasının yüksek basınçta sıfırıncı mertebe davranması hangi nedenle açıklanır?', 'Katalizör yüzeyinin NH₃ ile doymuş olması', ['NH₃ derişiminin sıfır olması', 'Platinin tepkimede harcanması', 'Tepkimenin gaz fazında yürümesi'], 'Yüzeydeki tüm aktif bölgeler dolu olunca gaz derişimi artsa da hız artmaz; hız yüzey bölgelerinin sayısı ile sınırlı kalır.'),
  ('İki basamaklı bir mekanizmada birinci basamak çok hızlı geri dönüşümlü, ikinci basamak yavaştır. Bu durumda gözlenen hız ifadesinde ara ürün derişimi hangi yolla ifadeden çıkarılır?', 'Ön denge sabiti kullanılarak', ['Yavaş basamağın ΔH değeri kullanılarak', 'Hız ifadesine hiç girmez', 'Toplam basınca bölünerek'], 'Hızlı ön denge K = [ara ürün]/[girenler] ifadesiyle ara ürün derişimi girenler cinsinden yazılır ve yavaş basamak hız ifadesine konur.'),
  ('ΔH°f değerleri C₆H₁₂O₆(k) −1273, C₂H₅OH(s) −277 ve CO₂(g) −394 kJ/mol\'dür. Alkollü fermantasyon C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ için ΔH kaç kJ\'dir?', '−69', ['+69', '−1342', '+1342'], 'ΔH = [2(−277) + 2(−394)] − (−1273) = −1342 + 1273 = −69 kJ; fermantasyon hafif ekzotermiktir.'),
  ('ΔH°f değerleri C₆H₁₂O₆(k) −1273, CO₂(g) −394 ve H₂O(s) −286 kJ/mol\'dür. Fotosentez 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ için ΔH yaklaşık kaç kJ\'dir?', '+2807', ['−2807', '+1273', '−1273'], 'ΔH = [−1273 + 0] − [6(−394) + 6(−286)] = −1273 + 4080 = +2807 kJ. Büyük pozitif değer enerji girdisini (ışık) gösterir.'),
  ('Yanma entalpileri C₂H₄(g) −1411, C₂H₆(g) −1560 ve H₂(g) −286 kJ/mol\'dür. C₂H₄ + H₂ → C₂H₆ hidrojenlenmesinin ΔH değeri kaç kJ\'dir?', '−137', ['+137', '−3257', '−1274'], 'ΔH = Σ(girenlerin yanma ısıları) − Σ(ürünlerin yanma ısıları) = (−1411 − 286) − (−1560) = −137 kJ.'),
  ('Bir süreçte ΔH = −100 kJ, ΔS_sistem = −150 J/K ve T = 300 K\'dir. Evrenin toplam entropi değişimi (ΔS_evren = ΔS_sistem − ΔH/T) kaç J/K\'dir?', '+183', ['−183', '+483', '−150'], 'Çevrenin entropi değişimi −ΔH/T = 100 000/300 ≈ +333 J/K\'dir. Toplam = −150 + 333 ≈ +183 J/K; süreç istemlidir.'),
  ('1 mol ideal gaz sabit sıcaklıkta hacmi iki katına çıkacak biçimde boşluğa serbestçe genleşiyor. Entropi değişimi ΔS = nR ln(V₂/V₁) bağıntısıyla yaklaşık kaç J/K\'dir? (R = 8,314 J/(mol·K), ln 2 = 0,693)', '+5,76', ['−5,76', '+8,310', '0'], 'ΔS = 1 × 8,314 × 0,693 ≈ +5,76 J/K. Hacim arttıkça mikro durum sayısı büyür ve entropi artar.'),
  ('Çarpışma teorisinin ötesine geçerek tepkime hızını aktifleşmiş kompleksin (geçiş hâlinin) niteliklerine bağlayan geçiş hâli teorisinin geliştiricilerinden biri kimdir?', 'Henry Eyring', ['Dmitri Mendeleev', 'Niels Bohr', 'Michael Faraday'], 'Eyring (ve Polanyi) 1935\'te tepkimenin tepe noktasındaki aktifleşmiş kompleksle girenler arasında denge varsayarak hız sabitini hesaplamayı sağlayan teoriyi geliştirmiştir.'),
  ('Bir tepkimenin hız sabiti 300 K\'de k₁, 310 K\'de 2k₁ olarak ölçülüyor. Aktifleşme enerjisi yaklaşık kaç kJ/mol\'dür? (R = 8,314 J/(mol·K), ln 2 = 0,693)', '53,6', ['5,36', '107,0', '26,8'], 'Ea = R·ln(k₂/k₁)/(1/T₁ − 1/T₂) = 8,314 × 0,693 / (1,075×10⁻⁴) ≈ 53 600 J/mol ≈ 53,6 kJ/mol.'),
  ('Deneyde 300 K\'de 1,0×10⁻³ s⁻¹ ve 320 K\'de 4,0×10⁻³ s⁻¹ hız sabitleri bulunan bir tepkime için Arrhenius denkleminden hesaplanacak aktifleşme enerjisi yaklaşık kaç kJ/mol\'dür? (ln 4 = 1,386)', '55', ['27', '110', '5,5'], 'Ea = 8,314 × 1,386 / (1/300 − 1/320) = 11,52 / (2,083×10⁻⁴) ≈ 55 300 J/mol ≈ 55 kJ/mol.'),
  ('Birinci mertebeden bir tepkimenin hız sabiti 0,0462 dk⁻¹\'dir. Girenin %90\'ının harcanması için gereken süre yaklaşık kaç dakikadır? (ln 10 = 2,303)', '50', ['15', '30', '100'], '%90 harcanınca [A]₀/[A] = 10\'dur. t = ln 10 / k = 2,303 / 0,0462 ≈ 50 dk.'),
  ('İkinci mertebeden bir tepkimede k = 0,20 M⁻¹ s⁻¹ ve [A]₀ = 0,50 M\'dir. [A] değerinin 0,10 M\'ye düşmesi için kaç saniye gerekir? (1/[A] = 1/[A]₀ + kt)', '40', ['8', '2,0', '10'], '1/0,10 = 1/0,50 + 0,20t → 10 = 2 + 0,20t ve t = 40 s.'),
  ('Ea = 50 kJ/mol olan bir tepkimede 300 K\'de aktifleşme enerjisini aşan taneciklerin oranı e^(−Ea/RT) bağıntısıyla yaklaşık hangi büyüklüktedir? (R = 8,314 J/(mol·K))', '≈ 10⁻⁹', ['≈ 10⁻¹', '≈ 10⁻⁵', '≈ 10⁻²⁰'], 'Ea/RT = 50 000/(8,314 × 300) ≈ 20,0 olduğundan oran e^(−20) ≈ 2×10⁻⁹\'dur; yani taneciklerin çok küçük bir kesri etkin çarpışma yapabilir.'),
  ('1 L\'lik kapta 1 mol H₂ ve 1 mol I₂ ile başlanıyor. H₂ + I₂ ⇌ 2HI dengesinin Kc değeri 50 ise dengede [HI] yaklaşık kaç M olur?', '1,56', ['0,780', '0,22', '2,00'], 'H₂\'den x mol harcanırsa (2x)²/(1−x)² = 50, 2x/(1−x) = 7,07 ve x ≈ 0,78 olur. [HI] = 2x ≈ 1,56 M.'),
  ('0,50 M N₂O₄ ile başlanan N₂O₄ ⇌ 2NO₂ dengesinde Kc = 0,40\'tır. Dengedeki [NO₂] yaklaşık kaç M\'dir?', '0,36', ['0,18', '0,500', '0,72'], '4x² = 0,40(0,50 − x) denkleminden x ≈ 0,179 M bulunur. [NO₂] = 2x ≈ 0,36 M.'),
  ('Başlangıçta 0,50 M PCl₅ bulunan kapta PCl₅ ⇌ PCl₃ + Cl₂ dengesinin Kc değeri 0,050\'dir. PCl₅\'in yüzde kaçı ayrışmıştır?', '27', ['10,0', '50', '5'], 'x²/(0,50 − x) = 0,050 denkleminden x ≈ 0,135 M bulunur. Ayrışma oranı 0,135/0,50 ≈ %27\'dir.'),
  ('1 L\'lik kapta 1 mol N₂ ve 3 mol H₂ ile başlanıyor. Dengede N₂\'nin yarısı harcanmıştır. N₂ + 3H₂ ⇌ 2NH₃ için Kc kaçtır?', '0,59', ['1,69', '0,300', '2,00'], 'Dengede N₂ 0,5; H₂ 1,5; NH₃ 1,0 mol\'dür. Kc = 1²/(0,5 × 1,5³) = 1/1,6875 ≈ 0,59.'),
  ('100 °C ve 1 atm\'de 1 mol suyun buharlaşması sırasında gazın çevreye karşı yaptığı iş (w = −nRT, ideal gaz) yaklaşık kaç kJ\'dir? (R = 8,314 J/(mol·K))', '3,1 kJ', ['40,7 kJ', '0,31 kJ', '31 kJ'], '|w| = nRT = 1 × 8,314 × 373 ≈ 3100 J ≈ 3,1 kJ\'dir. Buharlaşma entalpisinin (40,7 kJ) küçük bir kısmı genleşme işine gider.'),
  ('C–H bağı yerine C–D (döteryum) bağı bulunan bir bileşiğin bağ kırılmasının hız belirleyici olduğu tepkimede hız genellikle neden yavaşlar?', 'C–D bağının sıfır noktası enerjisi daha düşüktür', ['Döteryum atomu katalizörün yüzeyini kaplayıp zehirler', 'C–D bağı, C–H bağından daha zayıf olduğu için yavaştır', 'Döteryum, ortamın sıcaklığını kendiliğinden düşürür'], 'Daha ağır döteryumlu bağın titreşim (sıfır noktası) enerjisi daha düşüktür; bağı kırmak için gereken etkin aktifleşme enerjisi biraz artar. Bu olaya kinetik izotop etkisi denir.'),
  ('Hemoglobinin O₂ bağlaması Hb + O₂ ⇌ HbO₂ dengesiyle gösterilirse, çalışan kasta CO₂ ve H⁺ artışı oksijenin dokuya bırakılmasını (Bohr etkisi) kolaylaştırır. Bunun denge açısından yorumu nedir?', 'H⁺ artışı dengeyi O₂ bırakma yönüne kaydırır', ['H⁺ artışı hemoglobine O₂ bağlanmasını artırır', 'CO₂ artışı hemoglobin dengesinde hiçbir değişim yapmaz', 'Denge sabiti O₂ ile birlikte artar'], 'Asitlik artınca hemoglobinin O₂\'ye ilgisi azalır; HbO₂ oksijeni bırakır. Bu fizyolojik adaptasyon, ihtiyaç duyulan dokuda daha çok oksijen verilmesini sağlar.'),
  ('2SO₂ + O₂ ⇌ 2SO₃ dengesinin belirli bir sıcaklıktaki Kc değeri 100 M⁻¹\'dir. Dengede [SO₂] = 0,10 M ve [O₂] = 0,050 M ise [SO₃] yaklaşık kaç M\'dir?', '0,22', ['0,50', '0,050', '2,2'], '[SO₃]² = Kc[SO₂]²[O₂] = 100 × 0,010 × 0,050 = 0,050 ve [SO₃] ≈ 0,22 M.'),
  ('Standart oluşum serbest enerjileri CaCO₃ −1129, CaO −604 ve CO₂ −394 kJ/mol\'dür. CaCO₃ → CaO + CO₂ için ΔG° kaç kJ\'dir ve 298 K\'de tepkime nasıldır?', '+131; istemsiz', ['−131; istemli', '+1131; istemsiz', '−1131; istemli'], 'ΔG° = (−604 − 394) − (−1129) = +131 kJ. Pozitif olduğundan kireç taşı 298 K\'de ayrışmaz; yüksek sıcaklık gerekir.'),
  ('Sabit sıcaklıkta (300 K) gaz fazında bir tepkimede kısmi basınç değişimi dP/dt = 0,082 atm/s ölçülüyor. Bu hız derişim cinsinden yaklaşık kaç M/s\'dir? (R = 0,082 L·atm/(mol·K))', '3,3×10⁻³', ['8,20×10⁻²', '2,5', '1,0×10⁻⁴'], 'İdeal gazda c = P/RT olduğundan dc/dt = (dP/dt)/(RT) = 0,082/(0,082 × 300) ≈ 3,3×10⁻³ M/s.'),
  ('Bir katalizör aktifleşme enerjisini 75 kJ/mol\'den 50 kJ/mol\'e düşürüyor. A çarpanı değişmiyorsa 300 K\'de hız sabiti yaklaşık kaç katına çıkar? (R = 8,314 J/(mol·K), e^10 ≈ 2,2×10⁴)', '≈ 2×10⁴', ['≈ 25', '≈ 1,5', '≈ 10⁸'], 'k₂/k₁ = e^(ΔEa/RT) = e^(25 000/(8,314 × 300)) = e^10,0 ≈ 2×10⁴. Küçük bir Ea düşüşü hızı çok büyük ölçüde artırır.'),
  ('Bir tepkime sistemi için serbest enerjinin (G) ilerleme derecesine göre değişimi düşünüldüğünde denge noktası nasıl bir yere karşılık gelir?', 'Serbest enerjinin en düşük (minimum) olduğu noktaya', ['Serbest enerjinin en yüksek olduğu noktaya', 'Girenlerin saf hâlde olduğu başlangıca', 'Ürünlerin saf hâlde olduğu sona'], 'Sabit T ve P\'de kendiliğinden süreç G\'yi azaltır. Denge, G\'nin minimum olduğu ve ΔG = 0 olan noktadır; yalnız giren ya da yalnız ürün bu noktada değildir.'),
  ('2NO + 2H₂ → N₂ + 2H₂O tepkimesinde [H₂] sabitken [NO] iki katına çıkarılınca hız 4 katına, [NO] sabitken [H₂] iki katına çıkarılınca hız 2 katına çıkıyor. Bu tepkimenin toplam mertebesi ve hakkında yorumu hangisidir?', 'Toplam mertebe 3; katsayılar toplamı 4 olduğundan tek basamaklı değil', ['Toplam mertebe 4\'tür; katsayılar toplamı 4 olduğundan tek basamaklı olabilir', 'Toplam mertebe 2\'dir; tepkime tek basamaklıdır', 'Toplam mertebe 3\'tür; tepkime tek basamaklıdır'], 'Hız yasası r = k[NO]²[H₂] olup mertebe 3\'tür. Tek basamakta mertebe katsayılar toplamı olan 4 olurdu; ayrıca dört taneciğin çarpışması çok olasıksız olduğundan çok basamaklı bir mekanizma beklenir.'),
  ('2H₂O₂ → 2H₂O + O₂ ayrışmasında oluşan O₂\'nin hacmi normal koşullarda 12 mL/dk hızla artıyor (22,4 L/mol). Bu sırada H₂O₂\'nin harcanma hızı yaklaşık kaç mmol/dk\'dır?', '1,07', ['0,540', '2,14', '12'], '12 mL O₂ = 0,536 mmol\'dür. Denklemde 2 mol H₂O₂\'den 1 mol O₂ çıktığından H₂O₂ harcanma hızı 2 × 0,536 ≈ 1,07 mmol/dk\'dır.'),
  ('Bir kaba 0,10 mol CaCO₃ konup ısıtılıyor. CaCO₃(k) ⇌ CaO(k) + CO₂(g) dengesinde sıcaklıkta kabın hacmi 4,0 L ve Kc = 0,050 mol/L\'dir. Dengenin kurulabilmesi için hangisi doğrudur?', '0,20 mol CO₂ gerekir; 0,10 mol CaCO₃ yetmez, denge kurulmaz', ['0,10 mol CaCO₃ yeterlidir ve denge kolayca kurulur', 'Katı miktarı arttıkça Kc değeri de aynı oranda artar', 'Denge derişimi 0,10 mol/L CO₂ olacak biçimde kurulur'], 'Dengede [CO₂] = 0,050 M olmalı; 4,0 L\'de bu 0,20 mol CO₂ eder. Elde yalnızca 0,10 mol CaCO₃ olduğundan tamamı ayrışır, denge kurulamaz.'),
  ('Aktifleşme enerjisi 100 kJ/mol olan bir tepkimenin hız sabiti, sıcaklık 300 K\'den 600 K\'e çıkarıldığında yaklaşık kaç kat artar? (R = 8,314 J/(mol·K), e^20 ≈ 4,85×10⁸)', '≈ 5×10⁸', ['≈ 2', '≈ 100', '≈ 10³'], 'ln(k₂/k₁) = (100 000/8,314)(1/300 − 1/600) = 12 027 × 0,001667 ≈ 20,0. k₂/k₁ = e^20 ≈ 5×10⁸.'),
  ('Basit bir ikinci mertebe tepkimede iki katı derişim yarı ömrü nasıl etkiler ve bu bilgi mertebe tayininde nasıl kullanılır?', 'Yarı ömür başlangıç derişimiyle değiştiğinden mertebe yarı ömürlerin derişime bağlılığından belirlenir', ['Yarı ömür hiç değişmez; mertebe bulunamaz', 'Yarı ömür yalnız sıcaklığa bağlıdır', 'Yarı ömür her zaman sabit kalır'], 'Birinci mertebede t½ derişimden bağımsızdır. İkinci mertebede ters, sıfırıncıda doğru orantılı değişir; farklı [A]₀ ile ölçülen yarı ömürler mertebeyi gösterir.'),
  ('Bir tepkimenin enerji profilinde ürünlerin enerjisi, ileri yöndeki aktifleşmiş kompleksin enerjisinden daha yüksek olabilir mi?', 'Hayır; aktifleşmiş kompleks hem girenlerin hem ürünlerin üstündedir', ['Evet; ürünler her zaman en yüksek enerjidedir', 'Evet; yalnızca endotermik tepkimelerde', 'Hayır; yalnızca ekzotermik tepkimelerde'], 'Geçiş hâli, reaksiyon yolu üzerindeki en yüksek enerji noktasıdır; girenlerden ürünlere giderken ürünler dahil tüm enerji düzeylerinin üstündedir.'),
  ('NO(g) için ΔG°f = +87 kJ/mol\'dür; yani N₂ ve O₂\'ye göre termodinamik olarak kararsızdır. Buna karşın NO oda sıcaklığında uzun süre bozunmadan kalabilir. Bu durum nasıl açıklanır?', 'Bozunmanın aktifleşme enerjisi çok yüksektir; NO kinetik açıdan kararlıdır', ['Bozunma ekzotermik olmadığı için olamaz', 'NO\'nun ΔG°f değeri yanlış ölçülmüştür', 'Oda sıcaklığında entropi sıfırdır'], 'Termodinamik kararlılık (ΔG) ile kinetik kararlılık (hız) farklı kavramlardır. NO ayrışması için gerekli yüksek enerji bariyeri oda sıcaklığında aşılamadığından NO uzun süre kalır.'),
  ('N₂O₄(g) ⇌ 2NO₂(g) dengesinde 298 K\'de Kp = 0,14 atm\'dir. Toplam basınç 1,0 atm olduğunda N₂O₄\'ün yaklaşık yüzde kaçı ayrışmıştır? (Kp = 4α²P/(1 − α²))', '18', ['14', '37,0', '50'], 'α²(4P + Kp) = Kp bağıntısından α² = 0,14/4,14 ≈ 0,034 ve α ≈ 0,18 bulunur; yaklaşık %18 ayrışma vardır.'),
  ('N₂O₄ ⇌ 2NO₂ dengesinde Kp = 0,14 atm iken toplam basınç 1,0 atm\'den 0,10 atm\'e düşürülürse ayrışma derecesi yaklaşık nasıl değişir? (Kp = 4α²P/(1 − α²))', '%18\'den yaklaşık %51\'e çıkar', ['%18\'de kalır', '%18\'den %5\'e düşer', '%18\'den %100\'e çıkar'], 'α² = Kp/(4P + Kp) = 0,14/(0,40 + 0,14) ≈ 0,26 ve α ≈ 0,51. Basınç düşünce gaz mol sayısı artan ayrışma yönü desteklenir.'),
  ('Motor egzozundaki sıcak gaz hızla soğutulduğunda NO miktarı, düşük sıcaklığın dengesinin öngördüğünden çok yüksek kalır. Bunun nedeni nedir?', 'Düşük sıcaklıkta ayrışma hızı çok yavaşladığından denge \'donar\'', ['Düşük sıcaklıkta K büyür', 'Soğutma NO\'yu çoğaltır', 'NO\'nun ΔH değeri sıfırlanır'], 'Hızlı soğutmada NO → N₂ + O₂ dönüşümü kinetik olarak çok yavaşlar; sistem yüksek sıcaklıktaki bileşimi koruyarak \'donmuş denge\' hâlinde kalır.'),
  ('Özgül ısısı 0,385 J/(g·°C) olan bir metalin molar ısı kapasitesinin Dulong–Petit kuralına göre yaklaşık 25 J/(mol·°C) olduğu biliniyor. Bu metal aşağıdakilerden hangisi olabilir?', 'Bakır (63,5 g/mol)', ['Alüminyum (27 g/mol)', 'Kurşun (207 g/mol)', 'Magnezyum (24 g/mol)'], 'M ≈ 25 / 0,385 ≈ 65 g/mol bulunur. Bu değere en yakın element bakırdır (63,5 g/mol).'),
  ('Kapalı bir kapta C(k) + O₂(g) ⇌ CO₂(g) dengesinde sıcaklık sabitken kap hacmi yarıya indirilirse O₂\'nin denge derişimi, yeni dengede ilk dengeye göre nasıl olur?', 'İki katına çıkar; denge kaymaz', ['Aynı kalır, çünkü Kc sabittir', 'Yarıya düşer', 'Sıfır olur'], 'Gaz mol sayısı iki yanda eşit (Δn = 0) olduğundan hacim yarıya inince denge kaymaz. O₂ ve CO₂ derişimleri anlık iki katına çıkar ve oranları (Kc) aynı kalır.'),
  ('Belousov–Zhabotinsky tepkimesinde çözeltinin rengi düzenli aralıklarla değişir (osilasyon). Bu gözlem dengeyle ilgili hangi sonucu doğurur?', 'Sistem dengeden uzaktır; derişimler zamanla periyodik değişir', ['Sistem dengededir ve derişimler sabittir', 'Tepkime ikinci yasaya aykırıdır', 'Tepkime hiç hız sabitine sahip değildir'], 'Osilasyon yapan tepkimelerde ara ürün derişimleri dengeden uzak koşullarda periyodik değişir; toplam süreç yine de serbest enerjiyi azaltır ve ikinci yasayla çelişmez.'),
  ('100 g seyreltik HCl çözeltisine 0,60 g Mg (24 g/mol) atılıyor ve sıcaklık 28 °C artıyor (c = 4,18 J/(g·°C)). Mg + 2HCl → MgCl₂ + H₂ tepkimesinin Mg başına entalpi değişimi yaklaşık kaç kJ/mol\'dür? (Kalorimetre ısısı ihmal edilsin.)', '−468', ['+468', '−11,7', '−234'], 'q = 100 × 4,18 × 28 ≈ 11 700 J. Mg 0,025 mol olduğundan ΔH ≈ −11,7 kJ / 0,025 mol ≈ −468 kJ/mol.'),
  ('Sakkarozun suyla hidrolizinde (C₁₂H₂₂O₁₁ + H₂O → glikoz + fruktoz) hız polarimetreyle izlenebilir. Bunun nedeni nedir?', 'Karışımın optik dönme açısı sağdan sola doğru değişir', ['Çözeltinin rengi zamanla koyulaşır', 'Gaz çıkışı olur', 'Çözeltinin iletkenliği artar'], 'Sakkaroz sağa (+) çeviren, glikoz–fruktoz karışımı ise net olarak sola (−) çeviren bir sistemdir; dönme açısı zamanla değişir ve bu değişim tepkimenin ilerlemesini gösterir.'),
  ('n-Bütan ve izobütan aynı formüle (C₄H₁₀) sahiptir ve yanma entalpileri sırasıyla −2877 ve −2869 kJ/mol\'dür. Bu veri hangi sonuca götürür?', 'İzobütan, enerjice daha düşük (daha kararlı) bir izomerdir', ['n-Bütan daha kararlıdır', 'İkisinin kararlılığı eşittir', 'İzobütan yanmaz'], 'Aynı ürünler oluştuğundan yanma ısısı farkı girenlerin entalpi farkını gösterir. İzobütan daha az ısı verdiğinden başlangıç enerjisi daha düşüktür, yani daha kararlıdır.'),
  ('CO + H₂O ⇌ CO₂ + H₂ (ΔH < 0) su-gaz kayması iki kademede yürütülür: önce yüksek sıcaklık (≈ 400 °C), sonra düşük sıcaklık (≈ 200 °C). Bu uygulamanın nedeni nedir?', 'Yüksek T\'de hız, düşük T\'de büyük verim elde edilir', ['Düşük sıcaklıkta hız da verim de her zaman yüksektir', 'Yüksek sıcaklıkta K büyür', 'İki kademe ΔH\'ı değiştirir'], 'İlk kademede hız yüksek olduğundan büyük kısım hızla dönüşür; ekzotermik dengede düşük sıcaklık daha büyük K sağladığından ikinci kademe dönüşümü tamamlar.'),
  ('Haber–Bosch reaktörlerinde katalizör yatakları birden fazla kademede kurulur ve kademeler arasında gaz karışımı soğutulur. Bunun amacı nedir?', 'Isınan gazı soğutup dengeyi ürüne çekmek', ['Gazı ısıtıp oluşan NH₃\'ü yeniden ayrıştırmak', 'Basıncı sıfırlamak', 'Katalizörü kaldırmak'], 'Tepkime ısı verdiğinden sıcaklık yükseldikçe K azalır. Kademeler arası soğutma sıcaklığı düşürerek yeni bir kademede daha çok NH₃ oluşmasını sağlar.'),
  ('H₂ + I₂ → 2HI tepkimesi için klasik mekanizma: (1) I₂ ⇌ 2I (hızlı denge), (2) H₂ + 2I → 2HI (yavaş). Bu mekanizmaya göre hız ifadesi nedir?', 'r = k[H₂][I₂]', ['r = k[H₂][I]', 'r = k[H₂][I₂]²', 'r = k[I₂]'], 'Yavaş basamakta r = k₂[H₂][I]². Hızlı dengeden [I]² = K[I₂] olduğundan r = k₂K[H₂][I₂] = k[H₂][I₂] bulunur; bu deneysel yasayla uyumludur.'),
  ('2N₂O₅ → 4NO₂ + O₂ için önerilen mekanizma: (1) N₂O₅ ⇌ NO₂ + NO₃ (hızlı denge), (2) NO₂ + NO₃ → NO + O₂ + NO₂ (yavaş), (3) NO + NO₃ → 2NO₂ (hızlı). Hız ifadesi nedir?', 'r = k[N₂O₅]', ['r = k[N₂O₅]²', 'r = k[NO₂][NO₃]', 'r = k[NO][NO₃]'], 'Yavaş basamakta r = k₂[NO₂][NO₃]. Ön dengeden [NO₂][NO₃] = K[N₂O₅] olduğundan r = k₂K[N₂O₅] = k[N₂O₅], yani birinci mertebedir.'),
  ('2NO₂ ⇌ N₂O₄ dengesinde ileri ve geri tepkimeler temel basamaktır: r_ileri = k₁[NO₂]², r_geri = k₋₁[N₂O₄]. k₁ = 4,0×10³ M⁻¹ s⁻¹ ve k₋₁ = 1,0×10² s⁻¹ ise Kc kaçtır?', '40 M⁻¹', ['4,0×10⁻² M⁻¹', '4,0×10⁵ M⁻¹', '40 M'], 'Dengede hızlar eşit olduğundan k₁[NO₂]² = k₋₁[N₂O₄] ve Kc = [N₂O₄]/[NO₂]² = k₁/k₋₁ = 40 M⁻¹ bulunur.'),
];
